// B"H
// Boruch Hashem
// Blessed is He
//
// Awtsmoos Shliach — Browser Link (background service worker, Manifest V3).
//
// Shared across Minimal / Standard / Unrestricted. The per-version feature
// set comes from version.js (generated by build.mjs, loaded first via
// importScripts). The version decides what this worker may do:
//
//   Minimal      — active tab only, via chrome.scripting on user click.
//                  No debugger, no network log, no other tabs.
//   Standard     — any awtsmoos.com tab, via the declared content script.
//                  No debugger, no network log, no other sites.
//   Unrestricted — every tab, via chrome.debugger (the Network Logger's
//                  proven passive recorder), plus full response bodies and
//                  live network events streamed to the agent.
//
// What the agent can see, instantly, in every version:
//   page.html     — the raw HTML of the page (chunked, live DOM serialized)
//   page.dom      — the parsed DOM tree as JSON (capped depth / nodes)
//   page.summary  — a compact summary: headings, text, links, forms
//   page.elements — every clickable / selectable element, each with a
//                   stable selector the agent can click or fill with
// Stealth: Unrestricted reads the page through the debugger, outside the
// page's JavaScript context — no injected script, no content script, no
// navigator.webdriver flag, no network request, and the readers only read
// (they never mutate anything), so the page has nothing to detect. The
// only trace is Chrome's "debugging" banner, visible to you, not to the
// page. Standard and Minimal run the same pure readers from the content
// script's isolated world; the reads themselves are invisible, but the
// page can in principle detect that an extension is present.
//
// The Shliach Link (agent connection):
//   This worker opens ONE WebSocket to the Awtsmoos relay
//   (wss://awtsmoos.com/api/shliach/relay) and speaks the versioned
//   realtime protocol (application "shliach-browser", version 1). The agent
//   creates a short pairing code (it must be OAuth-verified to do so) and
//   shows it to you; you type the code into the popup; this worker joins
//   with the code (the code IS the authorization — no token lives in the
//   extension). From then on the relay forwards the agent's JSON commands
//   to this worker, and this worker sends the results back. The relay never
//   stores message contents; it only forwards them between the two paired
//   sockets. Codes expire after 10 minutes and pair exactly one browser.
//
// Security notes:
//   - The extension makes NO network requests of its own except the single
//     relay WebSocket to awtsmoos.com. It never fetches, beacons, or phones
//     home anywhere else.
//   - Unrestricted uses the debugger's Network domain passively (the same
//     approach as Network Logger): it never pauses, modifies, or injects
//     anything. The only observable trace is Chrome's "debugging" banner,
//     visible only to you.
//   - Minimal and Standard use a content script / scripting injection, so
//     the page CAN detect them (unlike the debugger approach). That is
//     stated on the download page; use Unrestricted when stealth matters.

importScripts("version.js", "extract.js");

const RELAY_URL = "wss://awtsmoos.com/api/shliach/relay";
const PROTOCOL = "awtsmoos.realtime";
const APP_ID = "shliach-browser";
const APP_VERSION = 1;
const RELAY_RECONNECT_MAX_MS = 30000;
const RELAY_RECONNECT_BASE_MS = 1000;
// The relay refuses any versioned message over 64 KiB (PAYLOAD_TOO_LARGE,
// 413). Results sent back to the agent must stay well under that, so the
// page readers chunk and cap their answers — and handleAgentCommand checks
// the size before sending and answers with a retry hint instead of a
// message the relay would drop.
const RELAY_SAFE_BYTES = 56 * 1024;
const SKIP_TYPES = new Set(["image", "media", "websocket"]);
const SKIP_SCHEMES = ["data:", "chrome:", "chrome-extension:", "about:", "blob:", "moz-extension:"];
const BODY_MAX_BYTES = 20 * 1024 * 1024;
const STOP_BODY_WAIT_MS = 1500;
const PROTOCOL_VERSION = "1.3";
const SAVE_DEBOUNCE_MS = 2000;

// ---------- state ----------
let relaySocket = null;
let relayState = "disconnected"; // disconnected | connecting | connected | paired
let pairingCode = "";
let sequence = 0;
let pendingRequests = new Map(); // requestId -> { resolve, reject, timer }
let reconnectTimer = null;
let reconnectDelayMs = RELAY_RECONNECT_BASE_MS;
let recording = false;
let startedAt = null;
let attachedTabs = new Set();
let pending = new Map();
let bodyFetches = new Set();
let entries = [];
let counts = {};
let saveTimer = null;
let networkStreaming = false;

const FEATURES = (globalThis.SHLIACH_VERSION && globalThis.SHLIACH_VERSION.features) || {};
const VERSION_ID = (globalThis.SHLIACH_VERSION && globalThis.SHLIACH_VERSION.id) || "unrestricted";

// ---------- persistence ----------
function markDirty() {
	if (saveTimer) return;
	saveTimer = setTimeout(() => {
		saveTimer = null;
		chrome.storage.local.set({
			shliach_state: { relayState, pairingCode, recording, startedAt, counts, networkStreaming },
			shliach_log: entries,
		});
	}, SAVE_DEBOUNCE_MS);
}

function restore() {
	chrome.storage.local.get(["shliach_state", "shliach_log"], (res) => {
		if (res.shliach_state) {
			pairingCode = res.shliach_state.pairingCode || "";
			recording = !!res.shliach_state.recording;
			startedAt = res.shliach_state.startedAt || null;
			counts = res.shliach_state.counts || {};
			networkStreaming = !!res.shliach_state.networkStreaming;
		}
		if (Array.isArray(res.shliach_log)) entries = res.shliach_log;
		updateBadge();
		if (recording && FEATURES.debugger) attachToAllTabs();
	});
}

function updateBadge() {
	const text = recording ? "REC" : relayState === "paired" ? "LINK" : "";
	chrome.action.setBadgeText({ text });
	if (recording) chrome.action.setBadgeBackgroundColor({ color: "#d93025" });
	else if (relayState === "paired") chrome.action.setBadgeBackgroundColor({ color: "#1a73e8" });
}

// ---------- relay client ----------
function nextRequestId() {
	sequence += 1;
	return "req-" + sequence + "-" + Date.now().toString(36);
}

function sendRelayEnvelope(type, payload) {
	if (!relaySocket || relaySocket.readyState !== WebSocket.OPEN) {
		return Promise.reject(new Error("relay not connected"));
	}
	const requestId = nextRequestId();
	const envelope = {
		protocol: PROTOCOL,
		application: APP_ID,
		version: APP_VERSION,
		type,
		requestId,
		sequence,
		payload: payload || {},
	};
	return new Promise((resolve, reject) => {
		const timer = setTimeout(() => {
			pendingRequests.delete(requestId);
			reject(new Error("relay request timed out: " + type));
		}, 15000);
		pendingRequests.set(requestId, { resolve, reject, timer });
		try {
			relaySocket.send(JSON.stringify(envelope));
		} catch (e) {
			clearTimeout(timer);
			pendingRequests.delete(requestId);
			reject(e);
		}
	});
}

function handleRelayMessage(raw) {
	let data;
	try {
		data = JSON.parse(raw);
	} catch (e) {
		return;
	}
	if (data.application !== APP_ID) return;
	// A response carries the requestId of a pending request; an event does not.
	if (data.requestId && pendingRequests.has(data.requestId)) {
		const entry = pendingRequests.get(data.requestId);
		pendingRequests.delete(data.requestId);
		clearTimeout(entry.timer);
		if (data.type === "error") entry.reject(new Error((data.payload && data.payload.message) || "relay error"));
		else entry.resolve(data);
		return;
	}
	// Events from the relay (no requestId).
	if (data.type === "shliach.message") {
		const from = data.payload && data.payload.from;
		const message = data.payload && data.payload.data;
		if (from === "agent" && message) handleAgentCommand(message);
	} else if (data.type === "shliach.peer-left") {
		setRelayState("connected");
	} else if (data.type === "shliach.browser-joined") {
		setRelayState("paired");
	}
}

function setRelayState(state) {
	relayState = state;
	updateBadge();
	markDirty();
	chrome.runtime.sendMessage({ action: "relayState", state }).catch(() => {});
}

function connectRelay(code) {
	if (relaySocket && (relaySocket.readyState === WebSocket.OPEN || relaySocket.readyState === WebSocket.CONNECTING)) {
		return Promise.resolve({ ok: true, state: relayState });
	}
	pairingCode = String(code || "").trim().toUpperCase();
	if (!pairingCode) return Promise.reject(new Error("a pairing code is required"));
	setRelayState("connecting");
	return new Promise((resolve, reject) => {
		let settled = false;
		let socket;
		try {
			socket = new WebSocket(RELAY_URL);
		} catch (e) {
			setRelayState("disconnected");
			reject(e);
			return;
		}
		relaySocket = socket;
		socket.onopen = () => {
			sendRelayEnvelope("shliach.join", { code: pairingCode, role: "browser", version: VERSION_ID })
				.then(() => {
					settled = true;
					reconnectDelayMs = RELAY_RECONNECT_BASE_MS;
					setRelayState("paired");
					chrome.storage.local.set({ shliach_state: { relayState, pairingCode, recording, startedAt, counts, networkStreaming } });
					resolve({ ok: true, state: "paired" });
				})
				.catch((e) => {
					settled = true;
					try { socket.close(); } catch (_) {}
					setRelayState("disconnected");
					reject(e);
				});
		};
		socket.onmessage = (event) => handleRelayMessage(event.data);
		socket.onerror = () => {
			if (!settled) {
				settled = true;
				setRelayState("disconnected");
				reject(new Error("could not reach the Shliach relay"));
			}
		};
		socket.onclose = () => {
			relaySocket = null;
			for (const [, entry] of pendingRequests) {
				clearTimeout(entry.timer);
				entry.reject(new Error("relay disconnected"));
			}
			pendingRequests.clear();
			if (relayState === "paired" || relayState === "connected") {
				setRelayState("disconnected");
				scheduleReconnect();
			} else {
				setRelayState("disconnected");
			}
		};
	});
}

function scheduleReconnect() {
	if (reconnectTimer || !pairingCode) return;
	const delay = reconnectDelayMs;
	reconnectDelayMs = Math.min(reconnectDelayMs * 2, RELAY_RECONNECT_MAX_MS);
	reconnectTimer = setTimeout(() => {
		reconnectTimer = null;
		if (!pairingCode) return;
		connectRelay(pairingCode).catch(() => {});
	}, delay);
}

function disconnectRelay() {
	pairingCode = "";
	if (reconnectTimer) {
		clearTimeout(reconnectTimer);
		reconnectTimer = null;
	}
	if (relaySocket) {
		try {
			sendRelayEnvelope("shliach.leave", {}).catch(() => {});
			relaySocket.close();
		} catch (_) {}
		relaySocket = null;
	}
	setRelayState("disconnected");
	chrome.storage.local.set({ shliach_state: { relayState, pairingCode, recording, startedAt, counts, networkStreaming } });
}

function sendToAgent(data) {
	if (relayState !== "paired") return Promise.resolve(false);
	return sendRelayEnvelope("shliach.send", { data })
		.then(() => true)
		.catch(() => false);
}

// ---------- agent command bridge ----------
async function handleAgentCommand(message) {
	let command;
	try {
		command = typeof message === "string" ? JSON.parse(message) : message;
	} catch (e) {
		return sendToAgent({ ok: false, error: "command was not valid JSON" });
	}
	if (!command || typeof command !== "object" || !command.command) {
		return sendToAgent({ ok: false, error: "command needs a command field" });
	}
	let result;
	try {
		result = await executeCommand(command);
	} catch (e) {
		return sendToAgent({ ok: false, command: command.command, id: command.id || null, error: String((e && e.message) || e) });
	}
	const reply = { ok: true, command: command.command, id: command.id || null, result };
	// Never send a message the relay would reject for size: answer with a
	// retry hint instead, so the agent knows to ask for a smaller chunk.
	let replyBytes = 0;
	try { replyBytes = new TextEncoder().encode(JSON.stringify(reply)).length; } catch (e) { replyBytes = 0; }
	if (replyBytes > RELAY_SAFE_BYTES) {
		return sendToAgent({
			ok: false,
			command: command.command,
			id: command.id || null,
			error: "result is " + replyBytes + " bytes, over the relay's 64 KiB limit — retry page.html with a smaller length, or page.dom / page.elements with a smaller limit",
			bytes: replyBytes,
		});
	}
	return sendToAgent(reply);
}

async function executeCommand(command) {
	const name = command.command;
	if (name === "ping") {
		return {
			version: VERSION_ID,
			name: (globalThis.SHLIACH_VERSION && globalThis.SHLIACH_VERSION.name) || "Awtsmoos Shliach — Browser Link",
			features: FEATURES,
			relay: relayState,
			recording,
			entries: entries.length,
		};
	}
	if (name === "tabs.list") return listTabs();
	if (name === "page.read") return pageRead(command.tabId);
	if (name === "page.html") return pageHtml(command.tabId, command.start, command.length);
	if (name === "page.dom") return pageDom(command.tabId, command.maxDepth, command.maxNodes);
	if (name === "page.summary") return pageSummary(command.tabId, command.maxText);
	if (name === "page.elements") return pageElements(command.tabId, command.limit);
	if (name === "page.click") return pageClick(command.tabId, command.selector);
	if (name === "page.fill") return pageFill(command.tabId, command.selector, command.value);
	if (name === "page.navigate") return pageNavigate(command.tabId, command.url);
	if (name === "page.evaluate") {
		if (!FEATURES.debugger) throw new Error("page.evaluate needs the Unrestricted version (debugger permission)");
		return pageEvaluate(command.tabId, command.expression, command.awaitPromise);
	}
	if (name === "page.screenshot") {
		if (!FEATURES.debugger) throw new Error("page.screenshot needs the Unrestricted version (debugger permission)");
		return pageScreenshot(command.tabId);
	}
	if (name === "network.start" || name === "network.stop" || name === "network.download") {
		if (!FEATURES.debugger) throw new Error("network recording needs the Unrestricted version (debugger permission)");
		if (name === "network.start") return startRecording();
		if (name === "network.stop") return stopRecording();
		return downloadHar();
	}
	if (name === "network.stream") {
		if (!FEATURES.debugger) throw new Error("network streaming needs the Unrestricted version (debugger permission)");
		networkStreaming = !!command.enable;
		markDirty();
		return { streaming: networkStreaming };
	}
	throw new Error("unknown command: " + name);
}

async function listTabs() {
	if (FEATURES.tabs) {
		const tabs = await chrome.tabs.query({});
		return tabs.map((t) => ({ id: t.id, url: t.url || "", title: t.title || "", active: !!t.active }));
	}
	const tabs = await chrome.tabs.query({ active: true, currentWindow: true });
	return tabs.map((t) => ({ id: t.id, url: t.url || "", title: t.title || "", active: true }));
}

async function resolveTab(tabId) {
	if (tabId != null) {
		if (!FEATURES.tabs && !FEATURES.activeTabScripting) throw new Error("this version cannot address a tab by id");
		const tab = await chrome.tabs.get(tabId);
		if (!tab) throw new Error("no such tab: " + tabId);
		if (!FEATURES.tabs) {
			const [active] = await chrome.tabs.query({ active: true, currentWindow: true });
			if (!active || active.id !== tab.id) throw new Error("Minimal can only touch the active tab");
		}
		return tab;
	}
	const [active] = await chrome.tabs.query({ active: true, currentWindow: true });
	if (!active) throw new Error("no active tab");
	return active;
}

function pageRead(tabId) {
	if (FEATURES.debugger) return pageReadDebugger(tabId);
	return pageReadContent(tabId);
}

async function pageReadDebugger(tabId) {
	const tab = await resolveTab(tabId);
	await ensureDebugger(tab.id);
	const res = await chrome.debugger.sendCommand({ tabId: tab.id }, "Runtime.evaluate", {
		expression: "({ title: document.title, url: location.href, text: document.body ? document.body.innerText.slice(0, 20000) : '', links: [...document.querySelectorAll('a')].slice(0, 50).map(a => ({ text: (a.textContent || '').trim().slice(0, 80), href: a.href })) })",
		returnByValue: true,
	});
	if (res && res.exceptionDetails) throw new Error("page read failed in the tab");
	return res.result.value;
}

async function pageReadContent(tabId) {
	const tab = await resolveTab(tabId);
	const results = await runInTab(tab, { action: "read" });
	return results;
}

// ---------- page readers: raw HTML, DOM tree, summary, clickable elements ----------
// Unrestricted reads through the debugger (stealth: outside the page's JS
// context, pure reads, nothing injected). Standard / Minimal run the same
// pure readers from the content script's isolated world (see extract.js).
const EXTRACT_FUNCTIONS = [extractPageHtml, extractPageDom, extractPageSummary, extractPageElements, stableSelector];

async function evaluateInPage(tabId, fnName, args) {
	const tab = await resolveTab(tabId);
	await ensureDebugger(tab.id);
	// Serialize the readers themselves into the page: they run inside an
	// IIFE, define no globals, mutate nothing, and only read the DOM — so
	// the page has nothing to detect.
	const fns = EXTRACT_FUNCTIONS.map((f) => f.toString()).join("\n");
	const expression = "(function(){\n" + fns + "\nreturn " + fnName + "(" + JSON.stringify(args || {}) + ");\n})()";
	const res = await chrome.debugger.sendCommand({ tabId: tab.id }, "Runtime.evaluate", {
		expression,
		returnByValue: true,
	});
	if (res && res.exceptionDetails) {
		throw new Error(fnName + " failed in the tab: " + ((res.exceptionDetails.exception && res.exceptionDetails.exception.description) || res.exceptionDetails.text || "unknown"));
	}
	if (!res || !res.result || res.result.value === undefined) {
		throw new Error(fnName + " returned nothing from the tab");
	}
	return res.result.value;
}

async function pageHtml(tabId, start, length) {
	if (FEATURES.debugger) return evaluateInPage(tabId, "extractPageHtml", { start, length });
	const tab = await resolveTab(tabId);
	return runInTab(tab, { action: "html", start, length });
}

async function pageDom(tabId, maxDepth, maxNodes) {
	if (FEATURES.debugger) return evaluateInPage(tabId, "extractPageDom", { maxDepth, maxNodes });
	const tab = await resolveTab(tabId);
	return runInTab(tab, { action: "dom", maxDepth, maxNodes });
}

async function pageSummary(tabId, maxText) {
	if (FEATURES.debugger) return evaluateInPage(tabId, "extractPageSummary", { maxText });
	const tab = await resolveTab(tabId);
	return runInTab(tab, { action: "summary", maxText });
}

async function pageElements(tabId, limit) {
	if (FEATURES.debugger) return evaluateInPage(tabId, "extractPageElements", { limit });
	const tab = await resolveTab(tabId);
	return runInTab(tab, { action: "elements", limit });
}

async function pageClick(tabId, selector) {
	if (!selector) throw new Error("page.click needs a selector");
	if (FEATURES.debugger) {
		const tab = await resolveTab(tabId);
		await ensureDebugger(tab.id);
		const res = await chrome.debugger.sendCommand({ tabId: tab.id }, "Runtime.evaluate", {
			expression: "(() => { const el = document.querySelector(" + JSON.stringify(selector) + "); if (!el) return { ok: false, error: 'no such element' }; el.click(); return { ok: true }; })()",
			returnByValue: true,
		});
		if (res && res.exceptionDetails) throw new Error("page click failed in the tab");
		return res.result.value;
	}
	const tab = await resolveTab(tabId);
	return runInTab(tab, { action: "click", selector });
}

async function pageFill(tabId, selector, value) {
	if (!selector) throw new Error("page.fill needs a selector");
	if (value === undefined) throw new Error("page.fill needs a value");
	if (FEATURES.debugger) {
		const tab = await resolveTab(tabId);
		await ensureDebugger(tab.id);
		const res = await chrome.debugger.sendCommand({ tabId: tab.id }, "Runtime.evaluate", {
			expression: "(() => { const el = document.querySelector(" + JSON.stringify(selector) + "); if (!el) return { ok: false, error: 'no such element' }; const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value') || Object.getOwnPropertyDescriptor(window.HTMLTextAreaElement.prototype, 'value'); if (setter && setter.set) setter.set.call(el, " + JSON.stringify(String(value)) + "); else el.value = " + JSON.stringify(String(value)) + "; el.dispatchEvent(new Event('input', { bubbles: true })); el.dispatchEvent(new Event('change', { bubbles: true })); return { ok: true }; })()",
			returnByValue: true,
		});
		if (res && res.exceptionDetails) throw new Error("page fill failed in the tab");
		return res.result.value;
	}
	const tab = await resolveTab(tabId);
	return runInTab(tab, { action: "fill", selector, value: String(value) });
}

async function pageNavigate(tabId, url) {
	if (!url) throw new Error("page.navigate needs a url");
	const tab = await resolveTab(tabId);
	if (FEATURES.tabs) {
		await chrome.tabs.update(tab.id, { url });
		return { ok: true, url };
	}
	return runInTab(tab, { action: "navigate", url });
}

async function pageEvaluate(tabId, expression, awaitPromise) {
	const tab = await resolveTab(tabId);
	await ensureDebugger(tab.id);
	const res = await chrome.debugger.sendCommand({ tabId: tab.id }, "Runtime.evaluate", {
		expression: String(expression || ""),
		returnByValue: true,
		awaitPromise: !!awaitPromise,
	});
	if (res && res.exceptionDetails) {
		throw new Error("evaluate failed: " + ((res.exceptionDetails.exception && res.exceptionDetails.exception.description) || res.exceptionDetails.text || "unknown"));
	}
	return res.result.value;
}

async function pageScreenshot(tabId) {
	const tab = await resolveTab(tabId);
	await ensureDebugger(tab.id);
	const res = await chrome.debugger.sendCommand({ tabId: tab.id }, "Page.captureScreenshot", { format: "png" });
	return { dataUrl: "data:image/png;base64," + res.data };
}

// Runs a small action inside a tab without the debugger.
// Standard: the declared content script answers. Minimal: inject content.js
// into the ACTIVE tab on demand (the user clicked the extension, so
// activeTab grants this one tab). The content script runs in the extension's
// isolated world: it sees the DOM but not the page's own JavaScript
// variables. That limit is stated on the download page.
async function runInTab(tab, message) {
	if (FEATURES.contentScript) {
		const response = await chrome.tabs.sendMessage(tab.id, message);
		if (response && response.ok === false) throw new Error(response.error || "content script failed");
		return response;
	}
	if (FEATURES.activeTabScripting) {
		await chrome.scripting.executeScript({ target: { tabId: tab.id }, files: ["content.js"] });
		const response = await chrome.tabs.sendMessage(tab.id, message);
		if (response && response.ok === false) throw new Error(response.error || "content script failed");
		return response;
	}
	throw new Error("this version cannot run code in a tab");
}

// ---------- debugger attach / recorder (Unrestricted only) ----------
async function ensureDebugger(tabId) {
	if (attachedTabs.has(tabId)) return;
	try {
		await chrome.debugger.attach({ tabId }, PROTOCOL_VERSION);
	} catch (e) {
		throw new Error("could not attach the debugger to this tab (DevTools may already be open)");
	}
	try {
		await chrome.debugger.sendCommand({ tabId }, "Network.enable", {
			maxTotalBufferSize: 50 * 1024 * 1024,
			maxResourceBufferSize: BODY_MAX_BYTES,
		});
		await chrome.debugger.sendCommand({ tabId }, "Runtime.enable", {});
		await chrome.debugger.sendCommand({ tabId }, "Page.enable", {});
	} catch (e) {
		try { await chrome.debugger.detach({ tabId }); } catch (_) {}
		throw new Error("could not enable debugger domains on this tab");
	}
	attachedTabs.add(tabId);
}

async function attachToAllTabs() {
	let tabs = [];
	try {
		tabs = await chrome.tabs.query({});
	} catch (e) {
		return;
	}
	for (const tab of tabs) {
		if (tab.id == null) continue;
		if (tab.url && !tab.url.startsWith("http")) continue;
		try { await ensureDebugger(tab.id); } catch (_) {}
	}
}

async function detachFromAllTabs() {
	for (const tabId of [...attachedTabs]) {
		attachedTabs.delete(tabId);
		try { await chrome.debugger.detach({ tabId }); } catch (_) {}
	}
}

function shouldSkip(details) {
	if (SKIP_TYPES.has((details.type || "").toLowerCase())) return true;
	const url = details.url || "";
	for (const s of SKIP_SCHEMES) if (url.startsWith(s)) return true;
	return false;
}

function headerArray(headers) {
	if (!headers) return [];
	if (Array.isArray(headers)) return headers.map((h) => ({ name: h.name, value: h.value || "" }));
	return Object.entries(headers).map(([name, value]) => ({ name, value: String(value) }));
}

function queryArray(url) {
	try {
		const u = new URL(url);
		const out = [];
		u.searchParams.forEach((value, name) => out.push({ name, value }));
		return out;
	} catch (e) {
		return [];
	}
}

function decodedSize(text, isBase64) {
	if (isBase64) return Math.floor((text.length * 3) / 4);
	return new TextEncoder().encode(text).length;
}

function toHarEntry(rec) {
	const duration = rec.endMonotonic != null ? Math.round((rec.endMonotonic - rec.startMonotonic) * 1000) : -1;
	return {
		startedDateTime: new Date(rec.startWallMs).toISOString(),
		time: duration,
		request: {
			method: rec.method,
			url: rec.url,
			httpVersion: rec.protocol || "HTTP/1.1",
			cookies: [],
			headers: headerArray(rec.requestHeaders),
			queryString: queryArray(rec.url),
			postData: rec.postData ? { mimeType: rec.postDataMime || "", text: rec.postData } : undefined,
			headersSize: -1,
			bodySize: rec.postData ? new TextEncoder().encode(rec.postData).length : -1,
		},
		response: {
			status: rec.statusCode || 0,
			statusText: rec.statusLine || "",
			httpVersion: rec.protocol || "HTTP/1.1",
			cookies: [],
			headers: headerArray(rec.responseHeaders),
			content: {
				size: rec.encodedDataLength != null ? rec.encodedDataLength : -1,
				mimeType: rec.mimeType || "",
				text: "",
				encoding: undefined,
				comment: rec.bodySkipped || undefined,
			},
			redirectURL: "",
			headersSize: -1,
			bodySize: rec.encodedDataLength != null ? rec.encodedDataLength : -1,
		},
		cache: {},
		timings: { blocked: -1, dns: -1, connect: -1, send: 0, wait: duration, receive: 0, ssl: -1 },
		serverIPAddress: rec.ip || "",
		connection: "",
		_resourceType: rec.type,
		_tabId: rec.tabId,
		_fromCache: !!rec.fromCache,
		_error: rec.error || undefined,
	};
}

function finishRecord(rec) {
	const entry = toHarEntry(rec);
	entries.push(entry);
	pending.delete(rec.key);
	markDirty();
	return entry;
}

function fetchBody(tabId, requestId, entry) {
	const p = chrome.debugger
		.sendCommand({ tabId }, "Network.getResponseBody", { requestId })
		.then((res) => {
			if (res && typeof res.body === "string") {
				entry.response.content.text = res.body;
				entry.response.content.encoding = res.base64Encoded ? "base64" : undefined;
				entry.response.content.size = decodedSize(res.body, !!res.base64Encoded);
				markDirty();
			}
		})
		.catch(() => {})
		.finally(() => bodyFetches.delete(p));
	bodyFetches.add(p);
	return p;
}

function streamNetworkEvent(event) {
	if (!networkStreaming) return;
	sendToAgent({ ok: true, type: "network.event", event }).catch(() => {});
}

chrome.debugger.onEvent.addListener((source, method, params) => {
	if (source.tabId == null) return;
	const tabId = source.tabId;
	const key = tabId + ":" + params.requestId;
	if (!recording && !networkStreaming) return;
	if (method === "Network.requestWillBeSent") {
		if (pending.has(key)) {
			const old = pending.get(key);
			if (params.redirectResponse) {
				old.statusCode = params.redirectResponse.status;
				old.statusLine = params.redirectResponse.statusText || "";
				old.responseHeaders = params.redirectResponse.headers || null;
				old.endMonotonic = params.timestamp;
			} else {
				old.endMonotonic = old.endMonotonic || params.timestamp;
				if (old.loaderId !== params.loaderId) old.error = "superseded (requestId reused after navigation)";
			}
			finishRecord(old);
		}
		const req = params.request || {};
		if (shouldSkip({ type: params.type, url: req.url })) return;
		counts[params.type] = (counts[params.type] || 0) + 1;
		let postDataMime = "";
		if (req.headers) {
			for (const [n, v] of Object.entries(req.headers)) {
				if (n.toLowerCase() === "content-type") postDataMime = String(v).split(";")[0].trim();
			}
		}
		pending.set(key, {
			key, tabId, requestId: params.requestId, loaderId: params.loaderId || "",
			type: params.type, method: req.method || "GET", url: req.url || "",
			startMonotonic: params.timestamp, startWallMs: (params.wallTime || Date.now() / 1000) * 1000,
			requestHeaders: req.headers || null, postData: req.postData || null, postDataMime,
			responseHeaders: null, statusCode: 0, statusLine: "", protocol: "", mimeType: "",
			ip: "", fromCache: false, encodedDataLength: null, bodySkipped: null,
			endMonotonic: null, error: null,
		});
		markDirty();
		if (networkStreaming) streamNetworkEvent({ method, tabId, url: req.url, type: params.type });
	} else if (method === "Network.responseReceived") {
		const rec = pending.get(key);
		if (!rec) return;
		const resp = params.response || {};
		rec.statusCode = resp.status || 0;
		rec.statusLine = resp.statusText || "";
		rec.responseHeaders = resp.headers || null;
		rec.mimeType = resp.mimeType || "";
		rec.protocol = resp.protocol || "";
		rec.ip = resp.remoteIPAddress || "";
		rec.fromCache = !!(resp.fromDiskCache || resp.fromServiceWorker || resp.fromPrefetchCache);
		if (resp.encodedDataLength) rec.encodedDataLength = resp.encodedDataLength;
		if (networkStreaming) streamNetworkEvent({ method, tabId, url: rec.url, status: rec.statusCode });
	} else if (method === "Network.dataReceived") {
		const rec = pending.get(key);
		if (!rec) return;
		if (params.encodedDataLength) rec.encodedDataLength = (rec.encodedDataLength || 0) + params.encodedDataLength;
	} else if (method === "Network.requestServedFromCache") {
		const rec = pending.get(key);
		if (rec) rec.fromCache = true;
	} else if (method === "Network.loadingFinished") {
		const rec = pending.get(key);
		if (!rec) return;
		rec.endMonotonic = params.timestamp;
		if (params.encodedDataLength) rec.encodedDataLength = params.encodedDataLength;
		const entry = finishRecord(rec);
		const noBody = rec.statusCode === 204 || rec.statusCode === 304 || rec.statusCode === 0;
		const tooBig = rec.encodedDataLength && rec.encodedDataLength > BODY_MAX_BYTES;
		if (tooBig) {
			entry.response.content.comment = "body skipped: over " + BODY_MAX_BYTES + " bytes";
			markDirty();
		} else if (!noBody) {
			fetchBody(tabId, params.requestId, entry);
		}
		if (networkStreaming) streamNetworkEvent({ method, tabId, url: rec.url, status: rec.statusCode });
	} else if (method === "Network.loadingFailed") {
		const rec = pending.get(key);
		if (!rec) return;
		rec.endMonotonic = params.timestamp;
		rec.error = params.errorText || "net::ERR_FAILED";
		finishRecord(rec);
	}
});

chrome.debugger.onDetach.addListener((source, reason) => {
	if (source.tabId != null) attachedTabs.delete(source.tabId);
	if (recording && reason === "terminated" && source.tabId != null) {
		ensureDebugger(source.tabId).catch(() => {});
	}
});

chrome.tabs.onCreated.addListener((tab) => {
	if (recording && FEATURES.debugger && tab.id != null) ensureDebugger(tab.id).catch(() => {});
});

chrome.tabs.onUpdated.addListener((tabId, changeInfo) => {
	if (recording && FEATURES.debugger && changeInfo.url && !attachedTabs.has(tabId)) {
		ensureDebugger(tabId).catch(() => {});
	}
});

chrome.tabs.onRemoved.addListener((tabId) => {
	attachedTabs.delete(tabId);
	for (const [key, rec] of pending) {
		if (rec.tabId === tabId) pending.delete(key);
	}
});

// ---------- recording control ----------
async function startRecording() {
	entries = [];
	pending.clear();
	counts = {};
	recording = true;
	startedAt = Date.now();
	updateBadge();
	markDirty();
	await attachToAllTabs();
	return { ok: true, recording, attachedTabs: attachedTabs.size };
}

async function stopRecording() {
	recording = false;
	updateBadge();
	for (const rec of [...pending.values()]) finishRecord(rec);
	const wait = Promise.allSettled([...bodyFetches]);
	const timeout = new Promise((r) => setTimeout(r, STOP_BODY_WAIT_MS));
	await Promise.race([wait, timeout]);
	let filename = null;
	let error = null;
	try {
		filename = await downloadHar();
	} catch (e) {
		error = String((e && e.message) || e);
	}
	if (error) return { ok: false, error };
	await detachFromAllTabs();
	const count = entries.length;
	entries = [];
	counts = {};
	startedAt = null;
	chrome.storage.local.remove(["shliach_state", "shliach_log"]);
	return { ok: true, filename, count };
}

function buildHar() {
	return {
		log: {
			version: "1.2",
			creator: { name: "Awtsmoos Shliach — Browser Link", version: VERSION_ID },
			browser: { name: "Chrome", version: "" },
			pages: [],
			entries,
			comment: "Recorded by the Shliach Browser Link (Unrestricted) via the Chrome DevTools Protocol (Network domain only — passive observation, no page modification). Images/media skipped; all other response bodies captured in full (fonts as base64).",
		},
	};
}

async function downloadHar() {
	const har = buildHar();
	const json = JSON.stringify(har, null, 2);
	const stamp = new Date().toISOString().replace(/[:.]/g, "-").slice(0, 19);
	const filename = "shliach-log-" + stamp + ".har";
	try {
		await downloadViaDataUrl(filename, json);
		return filename;
	} catch (e) {
		return downloadViaOffscreen(filename, json);
	}
}

async function downloadViaDataUrl(filename, json) {
	const bytes = new TextEncoder().encode(json);
	let bin = "";
	for (let i = 0; i < bytes.length; i += 0x8000) {
		bin += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
	}
	await chrome.downloads.download({
		url: "data:application/json;base64," + btoa(bin),
		filename,
		saveAs: false,
	});
}

async function downloadViaOffscreen(filename, json) {
	if (!FEATURES.offscreen) throw new Error("offscreen download is not available in this version");
	if (!(await chrome.offscreen.hasDocument())) {
		await chrome.offscreen.createDocument({
			url: "offscreen.html",
			reasons: ["BLOBS"],
			justification: "Download the recorded HAR file. Service workers cannot create blob URLs, so a hidden document creates the download.",
		});
		await new Promise((r) => setTimeout(r, 200));
	}
	return new Promise((resolve, reject) => {
		const port = chrome.runtime.connect({ name: "offscreen-download" });
		const timer = setTimeout(() => {
			try { port.disconnect(); } catch (_) {}
			reject(new Error("offscreen download timed out"));
		}, 30000);
		port.onMessage.addListener((msg) => {
			clearTimeout(timer);
			try { port.disconnect(); } catch (_) {}
			if (msg && msg.ok) {
				chrome.offscreen.closeDocument().catch(() => {});
				resolve(msg.filename || filename);
			} else {
				reject(new Error((msg && msg.error) || "offscreen download failed"));
			}
		});
		port.onDisconnect.addListener(() => {
			clearTimeout(timer);
			reject(new Error("offscreen document disconnected"));
		});
		port.postMessage({ filename, json });
	});
}

// ---------- messages from the popup ----------
chrome.runtime.onMessage.addListener((msg, sender, sendResponse) => {
	(async () => {
		if (msg.action === "getState") {
			sendResponse({
				version: VERSION_ID,
				name: (globalThis.SHLIACH_VERSION && globalThis.SHLIACH_VERSION.name) || "Awtsmoos Shliach — Browser Link",
				features: FEATURES,
				relayState,
				pairingCode,
				recording,
				startedAt,
				count: entries.length,
				withBodies: entries.filter((e) => e.response.content.text).length,
				counts,
				inFlight: pending.size,
				attachedTabs: attachedTabs.size,
				networkStreaming,
			});
		} else if (msg.action === "connect") {
			try {
				const res = await connectRelay(msg.code);
				sendResponse({ ok: true, state: res.state });
			} catch (e) {
				sendResponse({ ok: false, error: String((e && e.message) || e) });
			}
		} else if (msg.action === "disconnect") {
			disconnectRelay();
			sendResponse({ ok: true });
		} else if (msg.action === "start") {
			if (!FEATURES.debugger) return sendResponse({ ok: false, error: "recording needs the Unrestricted version" });
			sendResponse(await startRecording());
		} else if (msg.action === "stop") {
			if (!FEATURES.debugger) return sendResponse({ ok: false, error: "recording needs the Unrestricted version" });
			sendResponse(await stopRecording());
		} else if (msg.action === "download") {
			if (!FEATURES.debugger) return sendResponse({ ok: false, error: "downloading the log needs the Unrestricted version" });
			try {
				const filename = await downloadHar();
				sendResponse({ ok: true, filename });
			} catch (e) {
				sendResponse({ ok: false, error: String((e && e.message) || e) });
			}
		} else if (msg.action === "clear") {
			entries = [];
			pending.clear();
			counts = {};
			chrome.storage.local.remove(["shliach_state", "shliach_log"]);
			sendResponse({ ok: true });
		}
	})();
	return true;
});

chrome.runtime.onInstalled.addListener(() => {
	updateBadge();
});

restore();
